mapper.select:
SELECT
crt.*,
book.BOOKSET_DATE booksetDateNew

FROM BOK_BOOKDETAIL_CURRENT crt
INNER JOIN (
SELECT
TEMP.happenDate,
TEMP.booksetDate,

TEMP.bookDate,
TEMP.bookId,
TEMP.booksetId
FROM (
SELECT
cur.HAPPEN_DATE as happenDate,

cur.BOOKSET_DATE as booksetDate,
cur.BOOK_DATE as
bookDate,
cur.BOOK_ID as bookId,
cur.BOOKSET_ID as
booksetId,
cur.OFFSET_FLAG as offsetFlag,
rn
FROM (
/* 子查询必加上rn字段 */
SELECT result.* FROM (
SELECT tmp.*,
@rownum := @rownum + 1 row, /* 虚拟列行标 */
IF(
(
@BOOKSET_ID = tmp.BOOKSET_ID and
@BOOK_ID = tmp.BOOK_ID
),
@rank := @rank + 1,
@rank := 1
) AS rn, /* 分组虚拟列行标 */
/* 下面的分组条件需要与oracle中 over (PARTITION BY xxx,xxx,xxx)顺序保持一至 */
@BOOKSET_ID := tmp.BOOKSET_ID /* 分组条件1 */
, @BOOK_ID := tmp.BOOK_ID /* 分组条件2 */
FROM (
/* 数据源 */
SELECT bc.*
FROM BOK_BOOKDETAIL_CURRENT bc
ORDER BY CAST(bc.BOOK_ORDER as SIGNED) DESC /* 按实际情况与oracle保持一至的排序 */
) tmp,
/* 定义临时变量池 */
(SELECT @rownum := 0,
@BOOKSET_ID := null,
@BOOK_ID = null,
@rank := 0) a
) result
) cur
WHERE 1=1
AND
cur.BOOKSET_ID = #{booksetId}
AND cur.BOOK_DATE <=
#{bookDate}
 AND cur.TABLE_ID = #{tableId}  
 AND cur.TRADE_ID = #{tradeId}  
 AND cur.HAPPEN_DATE = #{happenDate}  

	AND cur.HAPPEN_DATE >=
	#{beginHappenCycDate}


	AND cur.HAPPEN_DATE <=
	#{endHappenCycDate}

) TEMP
WHERE TEMP.rn = 1
AND TEMP.offsetFlag = #{offsetFlag}
) vr
on crt.happen_date = vr.happenDate
and crt.BOOKSET_DATE =
vr.booksetDate
and crt.BOOK_DATE = vr.bookDate
and crt.BOOK_ID =
vr.bookId
and crt.bookset_id = vr.booksetId
INNER JOIN BOK_BOOKSET_DATE
book ON book.BOOKSET_ID = crt.BOOKSET_ID
WHERE 1 =1


	AND crt.BASE_SUBJECT_NATURE IN

		#{baseSubjectNature}



	AND crt.BOK_DETAIL_ID = #{bokDetailId}


	AND ( crt.HAPPEN_DATE <=
	#{onwayDate} AND crt.ONWAY_DATE >
	#{onwayDate})

ORDER BY crt.HAPPEN_DATE ASC

SELECT T1.FINPROD_ID AS subcombinedCode, SUM(CASE WHEN T1.PS = #{tradeDirectionSubscribe} THEN T1.TRADE_AMT WHEN T1.PS = #{tradeDirectionRedemption} THEN -1 * T1.TRADE_AMT END) AS transactionAmount FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 INNER JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID AND T2.PA_BUSS_TYPE IN (#{productTradingCapitalAllocation},#{productCapitalAdjustment}) WHERE T1.TRADE_STATUS = #{transactionStatusInitial} AND T1.TRADE_DATE >= STR_TO_DATE(#{startDate},'%Y-%m-%d') AND STR_TO_DATE(#{endDate},'%Y-%m-%d') >= T1.TRADE_DATE AND (T1.FINPROD_ID IN
null) or T1.FINPROD_ID in (
#{code}
) GROUP BY T1.FINPROD_ID

SELECT tpda.PORTFOLIO_ID AS subcombinedCode, SUM(case when tpd.PS = '${tradeDirectionSubscribe}' then tpd.TRADE_AMT when tpd.PS = '${tradeDirectionRedemption}' then -1*tpd.TRADE_AMT end) AS transactionAmount FROM TRD_PRODUCT_DEAL tpd INNER JOIN TRD_PRODUCT_DEAL_ADD tpda ON tpd.TRADE_ID = tpda.TRADE_ID INNER JOIN PA_TRD_PRODUCT_DEAL ptpd ON ptpd.TRADE_ID = tpd.TRADE_ID AND ptpd.PA_BUSS_TYPE IN (#{productTradingCapitalAllocation},#{productCapitalAdjustment}) WHERE tpd.TRADE_STATUS <> #{transactionStatusInitial} AND tpd.IS_CANCEL = #{yes_no} AND DATE_FORMAT(tpd.TRADE_DATE,'%Y-%m-%d') <= #{endDate} AND (tpda.PORTFOLIO_ID in
null) or tpda.PORTFOLIO_ID in (
#{code}
) GROUP BY tpda.PORTFOLIO_ID
